import { readFileSync, writeFileSync, mkdirSync, readdirSync } from "node:fs";
import { join, resolve } from "node:path";

const out = resolve(new URL("./", import.meta.url).pathname.replace(/^\//, "").replaceAll("/", "\\"));
const graph = JSON.parse(readFileSync(join(out, "concept-graph.json"), "utf8"));
const pack = JSON.parse(readFileSync(join(out, "pack.json"), "utf8").replace(/^\uFEFF/, ""));
const pagesDir = join(out, "pages");

function readingPath(g) {
  const nodes = Object.fromEntries(g.nodes.map(n => [n.id, n]));
  const after = Object.fromEntries(g.nodes.map(n => [n.id, new Set()]));
  const indeg = Object.fromEntries(g.nodes.map(n => [n.id, 0]));
  for (const e of g.edges) {
    let first, later;
    if (e.kind === "prerequisite") [first, later] = [e.src, e.dst];
    else if (e.kind === "builds-on") [first, later] = [e.dst, e.src];
    else continue;
    if (nodes[first] && nodes[later] && !after[first].has(later)) { after[first].add(later); indeg[later]++; }
  }
  const key = id => [nodes[id].level ?? 0, nodes[id].label];
  const sort = xs => xs.sort((a,b) => key(a)[0] - key(b)[0] || key(a)[1].localeCompare(key(b)[1]));
  let ready = sort(Object.keys(nodes).filter(id => indeg[id] === 0));
  const order = [];
  while (ready.length) {
    const cur = ready.shift(); order.push(cur);
    for (const nxt of sort([...after[cur]])) if (--indeg[nxt] === 0) { ready.push(nxt); sort(ready); }
  }
  for (const id of sort(Object.keys(nodes))) if (!order.includes(id)) order.push(id);
  return order;
}

const pages = {};
for (const file of readdirSync(pagesDir).filter(f => f.endsWith(".md")).sort()) {
  const key = file.replace(/\.md$/i, "").replace(/^\d+_/, "");
  pages[key] = readFileSync(join(pagesDir, file), "utf8");
}

const path = readingPath(graph);
const tour = path.slice(0, 5).map((id, i) => {
  const tldr = pages[id]?.split("## Intuition", 1)[0].replace(/^.*?\{#tldr\}\s*/s, "").trim() ?? "Next stop on the dependency-ordered reading path.";
  const sentence = (tldr.match(/[^.!?]+[.!?]/)?.[0] ?? tldr).replace(/\s+/g, " ").slice(0, 180);
  return { order: i + 1, title: graph.nodes.find(n => n.id === id)?.label ?? id, description: sentence, nodeIds: [id] };
});

const children = {};
for (const e of graph.edges) if (e.kind === "part-of") (children[e.dst] ??= []).push(e.src);
const clusters = graph.nodes.filter(n => n.level === 1).map(n => ({ id: n.id, label: n.label, nodeIds: [n.id, ...(children[n.id] ?? [])] }));
const degree = Object.fromEntries(graph.nodes.map(n => [n.id, 0]));
for (const e of graph.edges) { degree[e.src]++; degree[e.dst]++; }
const centrality = Object.fromEntries(Object.entries(degree).map(([id, d]) => [id, graph.nodes.length > 1 ? +(d / (graph.nodes.length - 1)).toFixed(4) : 0]));
const trace = Object.keys(pages).map(nodeId => ({ nodeId, phase: "written", status: "ok", date: "2026-07-17" }));
const bundle = {
  meta: graph.meta,
  nodes: graph.nodes,
  edges: graph.edges,
  pages,
  notes: {},
  hotspots: [],
  clusters,
  tour,
  provenance: pack.extraction,
  centrality,
  eqIndex: {},
  trace,
  glossary: {},
  excerpts: {},
  dependentSide: { "part-of": "dst", prerequisite: "dst", "builds-on": "src" },
};

const staging = join(out, ".dashboard-src");
mkdirSync(join(staging, "src"), { recursive: true });
writeFileSync(join(staging, "src", "data.gen.ts"), "// generated by portable equivalent of dashboard/build_data.py\nexport const KE_DATA = " + JSON.stringify(bundle, null, 1) + ";\n", "utf8");
writeFileSync(join(out, "data-bundle.json"), JSON.stringify(bundle, null, 1) + "\n", "utf8");
console.log(JSON.stringify({ nodes: bundle.nodes.length, edges: bundle.edges.length, pages: Object.keys(bundle.pages).length, tour: bundle.tour.length, output: "data-bundle.json" }));
